private TreeNode<T> rotateRight(TreeNode<T> node) {
	// Error handling
	if (node == null) {
		throw new IllegalArgumentException("Cannot rotate a null node");
	}

	// Get the right child of the node
	TreeNode<T> rightChild = node.getRight();

	// Check if the right child is null
	if (rightChild == null) {
		throw new IllegalStateException("Cannot rotate a node with a null right child");
	}

	// Get the left child of the right child
	TreeNode<T> leftGrandChild = rightChild.getLeft();

	// Check if the left grand child is null
	if (leftGrandChild == null) {
		throw new IllegalStateException("Cannot rotate a node with a null left grand child");
	}

	// Perform the rotation
	node.setRight(leftGrandChild);
	rightChild.setLeft(node);

	return leftGrandChild;
}

