public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Class<?>[] arguments = parameterizedType.getActualTypeArguments();

    // Check if the target type is a raw type and if so, return the bound type
    if (targetType.isAssignableFrom(parameterizedType.getRawType())) {
        return arguments;
    }

    // Check if the target type is a type variable and if so, recursively resolve the type arguments
    if (targetType.isAssignableFrom(parameterizedType.getOwnerType())) {
        return resolveArguments(targetType.getTypeParameters()[0], targetType.getDeclaringClass());
    }

    // If none of the above cases match, return null to indicate that the arguments cannot be resolved
    return null;
}
