public static int nextPrime(int desiredCapacity) {
    // Check if the desiredCapacity is already prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Find the next prime number greater than the desiredCapacity
    int nextPrime = desiredCapacity + 1;
    while (!isPrime(nextPrime)) {
        nextPrime++;
    }

    // If the desiredCapacity is less than 1000, check if the next prime is within 11% of the desiredCapacity
    if (desiredCapacity < 1000 && Math.abs(desiredCapacity - nextPrime) / desiredCapacity > 0.11) {
        // If not, find the next prime number that is within 11% of the desiredCapacity
        int diff = (int) Math.ceil(desiredCapacity * 0.11);
        while (Math.abs(desiredCapacity - nextPrime) > diff) {
            nextPrime++;
        }
    }
    return nextPrime;
}

private static boolean isPrime(int num) {
    // Check if num is less than 2, which means it is not prime
    if (num < 2) {
        return false;
    }

    // Check if num is divisible by 2 to 10
    for (int i = 2; i <= 10 && num % i == 0; i++) {
        // If num is divisible by 2 to 10, it is not prime
        return false;
    }

    // If num is not divisible by 2 to 10, it is prime
    return true;
}
