public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int sz = str.length();
    StringBuilder out = new StringBuilder(sz);
    for (int x=0; x<sz; x++) {
        char ch = str.charAt(x);
        if (ch == '\\') {
            char next = str.charAt(x+1);
            int t = 0;
            switch (next) {
                case 'b': t = '\b'; break;
                case 'f': t = '\f'; break;
                case 'n': t = '\n'; break;
                case 'r': t = '\r'; break;
                case 't': t = '\t'; break;
                case '\\': t = '\\'; break;
                case '"': t = '"'; break;
                default:
                    if (next >= '0' && next <= '7') {
    t = Integer.parseInt(str.substring(x+1, x+4), 8);
                        out.append((char) t);
                        x += 3;
                        continue;
                    }
            }
            if (t != 0) {
                out.append(t);
                x++;
                continue;
            }
        }
        out.append(ch);
    }
    return out.toString();
}
