/**
* Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
* @param path the path to start from (usually a full file path)
* @param relativePath the relative path to apply(relative to the full file path above)
* @return the full file path that results from applying the relative path
*/
public static String applyRelativePath(String path, String relativePath) {
    // validate input parameters
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    // ensure path separators are consistent
    if (!path.contains("/") || !relativePath.contains("/")) {
        throw new IllegalArgumentException("Path separators must be \"/\"");
    }
    // extract parent path and filename components
    String parentPath = path.substring(0, path.lastIndexOf('/') + 1);
    String filename = path.substring(path.lastIndexOf('/') + 1);
    // combine parent path and relative path components
    String combinedPath = parentPath + relativePath;
    // remove any duplicate "/" characters
    combinedPath = combinedPath.replaceAll("/+", "/");
    // check for invalid characters in the combined path
    if (combinedPath.contains("..") || combinedPath.contains("//")) {
        throw new IllegalArgumentException("Invalid relative path");
    }
    // construct the full file path
    return combinedPath + filename;
}

