private void checkIfPackedField() throws IOException {
    if (this.packedFields != null && this.packedFields.hasNext()) {
        int tag = this.packedFields.readTag();
        if (WireFormat.getTagFieldNumber(tag) == this.currentFieldNumber) {
            int wireType = WireFormat.getTagWireType(tag);
            if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
                this.packedFieldLength = this.packedFields.readRawVarint32();
                this.packedFieldLimit = this.packedFields.pushLimit(this.packedFieldLength);
            } else {
                this.error = "Invalid wire type for packed field.";
                throw new IOException(this.error);
            }
        } else {
            this.error = "No packed field found for field number " + this.currentFieldNumber;
            throw new IOException(this.error);
        }
    }
}

